package cn.jingyu.deepseek;
import android.graphics.Color;import android.text.SpannableString;import android.text.style.ForegroundColorSpan;import java.util.*;import java.util.regex.*;
/** Conservative lexical highlighting. Keeps every original character for copying. */
public final class CodeHighlighter {
 private static final Map<String,String> WORDS=new HashMap<>();
 static {String c="auto bool break case catch char class const continue default delete do double else enum explicit extern false float for friend if inline int long namespace new null nullptr private protected public register return short signed sizeof static struct switch template this throw true try typedef typename union unsigned using virtual void volatile while";WORDS.put("c",c);WORDS.put("cpp",c);WORDS.put("java",c+" abstract assert boolean extends final finally implements import instanceof interface native package strictfp super synchronized throws transient");WORDS.put("python","and as assert async await break class continue def del elif else except False finally for from global if import in is lambda None nonlocal not or pass raise return True try while with yield");WORDS.put("javascript","async await break case catch class const continue debugger default delete do else export extends false finally for from function if import in instanceof let new null of return static super switch this throw true try typeof undefined var void while with yield");WORDS.put("typescript",WORDS.get("javascript")+" any boolean declare enum implements infer interface keyof namespace never number private protected public readonly string type unknown");WORDS.put("json","true false null");WORDS.put("bash","case do done elif else esac fi for function if in select then until while export local readonly return source");WORDS.put("sql","select from where join inner left right outer on as distinct insert into values update set delete create table drop alter null not and or in exists group by order having limit offset asc desc union all case when then else end primary key references true false");WORDS.put("matlab","break case catch classdef continue else elseif end for function global if otherwise parfor persistent return spmd switch try while");}
 public static String language(String name){String n=name.toLowerCase(Locale.ROOT).trim();if(n.equals("py"))return "python";if(n.equals("c++")||n.equals("cc")||n.equals("cxx"))return "cpp";if(n.equals("js")||n.equals("jsx"))return "javascript";if(n.equals("ts")||n.equals("tsx"))return "typescript";if(n.equals("sh")||n.equals("shell")||n.equals("zsh"))return "bash";if(n.equals("m"))return "matlab";return n;}
 public static CharSequence highlight(String language,String value,boolean dark){String name=language(language),words=WORDS.get(name);if(words==null||value.length()>500000)return value;Set<String> keywords=new HashSet<>(Arrays.asList(words.split(" ")));String strings="\"(?:\\\\.|[^\"\\\\])*\"|'(?:''|\\\\.|[^'\\\\])*'";String comments=name.equals("python")||name.equals("bash")?"#[^\\n]*":name.equals("sql")?"--[^\\n]*|(?s:/\\*.*?\\*/)":name.equals("matlab")?"%[^\\n]*":"//[^\\n]*|(?s:/\\*.*?\\*/)";
 String triple=name.equals("python")?"(?s:\"\"\".*?\"\"\"|'''.*?''')|":"";String number="(?<![\\w])(?:0[xX][0-9a-fA-F]+|\\d+(?:\\.\\d+)?(?:[eE][+-]?\\d+)?)[uUlLfF]?\\b";Pattern tokens=Pattern.compile(triple+strings+"|"+comments+"|"+number+"|\\b[A-Za-z_][A-Za-z_0-9]*\\b");Matcher matcher=tokens.matcher(value);SpannableString out=new SpannableString(value);while(matcher.find()){String token=matcher.group();int color=0;if(token.startsWith("\"")||token.startsWith("'"))color=Color.parseColor(dark?"#b4d892":"#527326");else if(token.startsWith("#")||token.startsWith("//")||token.startsWith("/*")||token.startsWith("--")||token.startsWith("%"))color=Color.parseColor(dark?"#92a99a":"#5f7265");else if(Character.isDigit(token.charAt(0)))color=Color.parseColor(dark?"#e8b68d":"#9b542d");else if(keywords.contains(name.equals("sql")?token.toLowerCase(Locale.ROOT):token))color=Color.parseColor(dark?"#c8b5ef":"#78549c");else {int end=matcher.end();while(end<value.length()&&Character.isWhitespace(value.charAt(end)))end++;if(end<value.length()&&value.charAt(end)=='(')color=Color.parseColor(dark?"#94c6ee":"#286b92");}if(color!=0)out.setSpan(new ForegroundColorSpan(color),matcher.start(),matcher.end(),33);}return out;}
}
